package com.tihai.utils;
import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.zip.*;
public final class ReviewDocx {
 private ReviewDocx(){}private static String xml(Object v){return String.valueOf(v==null?"":v).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]","");}
 private static void p(StringBuilder b,String style,String text){b.append("<w:p><w:pPr><w:pStyle w:val=\"").append(style).append("\"/></w:pPr><w:r><w:t xml:space=\"preserve\">").append(xml(text)).append("</w:t></w:r></w:p>");}
 private static void entry(ZipOutputStream z,String name,String data)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(data.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
 public static byte[] create(Map<String,Object> snapshot,boolean selfTest)throws IOException{
  Map<String,Object> course=(Map<String,Object>)snapshot.get("course");List<Map<String,Object>> qs=(List<Map<String,Object>>)snapshot.get("questions");StringBuilder b=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body>");
  p(b,"Title",String.valueOf(course.getOrDefault("name","课程"))+ (selfTest?" 自测题集":" 复习题集"));p(b,"Normal","用途：汇总当前已成功读取的题目。来源包括章节小测和独立作业；考试读题尚未接入，未收录。此文件不代表平台所有题目均已收录。");
  long verified=qs.stream().filter(q->Boolean.TRUE.equals(q.get("gradeable"))).count();p(b,"Normal","已收录 "+qs.size()+" 题，其中 "+verified+" 题可按平台公布答案自测。本人作答不等于正确答案；题库或 AI 答案会标为参考答案，不属于平台标准答案。");
  Map<String,Object> coverage=(Map<String,Object>)course.get("coverage");if(coverage!=null)p(b,"Normal","收录状态："+coverage.getOrDefault("message","")+"；章节已检查 "+coverage.getOrDefault("processed",0)+" / "+coverage.getOrDefault("total",0)+"。");
  String unit="",kind="";int n=0;
  for(Map<String,Object> q:qs){String k=String.valueOf(q.get("kind")),u=String.valueOf(q.get("unit"));if(!k.equals(kind)){p(b,"Heading1",k);kind=k;unit="";}if(!u.equals(unit)){p(b,"Heading2",u);unit=u;}p(b,"Question",(++n)+". "+q.get("title"));List options=(List)q.get("options");for(int oi=0;oi<options.size();oi++)p(b,selfTest&&oi==options.size()-1?"Normal":"Option",String.valueOf(options.get(oi)));if(selfTest&&options.isEmpty())p(b,"Normal","作答：____________________");if(Boolean.TRUE.equals(q.get("needsVision")))p(b,"Note","本题含图片或未解码内容，暂未完整离线收录，请核对原页面。");if(!selfTest)answer(b,q,n);}
  if(selfTest){p(b,"Heading1","答案与来源");n=0;for(Map<String,Object> q:qs)answer(b,q,++n);}
  b.append("<w:sectPr><w:pgSz w:w=\"11906\" w:h=\"16838\"/><w:pgMar w:top=\"1134\" w:right=\"1134\" w:bottom=\"1134\" w:left=\"1134\"/></w:sectPr></w:body></w:document>");
  ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(bytes)){
   entry(z,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/><Override PartName=\"/word/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml\"/></Types>");
   entry(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>");
   entry(z,"word/_rels/document.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");
   entry(z,"word/document.xml",b.toString());StringBuilder styles=new StringBuilder("<w:styles xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii=\"Calibri\" w:eastAsia=\"微软雅黑\"/><w:sz w:val=\"22\"/><w:color w:val=\"000000\"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after=\"100\" w:line=\"300\" w:lineRule=\"auto\"/></w:pPr></w:pPrDefault></w:docDefaults>");
   for(String style:Arrays.asList("Normal","Title","Heading1","Heading2","Question","Option","Answer","Note")){styles.append("<w:style w:type=\"paragraph\" w:styleId=\"").append(style).append("\"><w:name w:val=\"").append(style).append("\"/><w:pPr>");if(Arrays.asList("Title","Heading1","Heading2","Question","Option","Answer").contains(style))styles.append("<w:keepNext/>");styles.append("</w:pPr><w:rPr>");if(Arrays.asList("Title","Heading1","Heading2","Question").contains(style))styles.append("<w:b/>");styles.append("<w:sz w:val=\"").append(style.equals("Title")?"36":style.equals("Heading1")?"28":style.equals("Heading2")?"24":"22").append("\"/><w:color w:val=\"000000\"/></w:rPr></w:style>");}styles.append("</w:styles>");entry(z,"word/styles.xml",styles.toString());
  }return bytes.toByteArray();
 }
 private static void answer(StringBuilder b,Map<String,Object> q,int n){String official=String.valueOf(q.getOrDefault("platformAnswer",""));p(b,"Answer",n+". 平台公布答案："+(official.isEmpty()?"尚未公布，不作为平台标准判分依据":official));String reference=String.valueOf(q.getOrDefault("referenceAnswer",""));if(!reference.isEmpty())p(b,"Answer",q.get("referenceSource")+"："+reference+"（非平台标准答案，可能有误）");String own=String.valueOf(q.getOrDefault("studentAnswer",""));if(!own.isEmpty())p(b,"Answer","本人作答："+own+"（不代表正确答案）");String exp=String.valueOf(q.getOrDefault("explanation",""));p(b,"Answer","平台解析："+(exp.isEmpty()?"未读取到公布解析":exp));p(b,"Note","来源："+q.get("kind")+" / "+q.get("unit"));}
}
